import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;

    public Account(String accountId, String holderName, BigDecimal balance) {
            this.accountId = accountId;
            this.holderName = holderName
            this.balance = balance;
    }
    public String accountId() { return accountId; }
    public String holderName() { return holderName; }
    public BigDecimal balance() { return balance; }
    // A virtual method we'll call via a MethodHandle.
    public BigDecimal withFee(BigDecimal fee) { return balance.subtract(fee); }
}
