package com.bank.mh.serde;

import com.bank.mh.model.Account;
import java.lang.invoke.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class HandleSerializer {
    private static final Logger log = Logger.getLogger(HandleSerializer.class.getName());

    // Handles are created ONCE (type-checked here) and cached for fast repeated use.
    private final MethodHandle getId;
    private final MethodHandle getHolder;
    private final MethodHandle getBalance;
    private final MethodHandle ctor;
    private final MethodHandle withFee;

    public HandleSerializer() {
        try {
            MethodHandles.Lookup lookup = MethodHandles.lookup();  // carries THIS class's access

            // findVirtual: instance accessor methods. MethodType = return + params.
            getId      = lookup.findVirtual(Account.class, "accountId",  MethodType.methodType(String.class));
            getHolder  = lookup.findVirtual(Account.class, "holderName", MethodType.methodType(String.class));
            getBalance = lookup.findVirtual(Account.class, "balance",    MethodType.methodType(BigDecimal.class));

            // findConstructor: MethodType returns void, lists the ctor parameter types.
            ctor = lookup.findConstructor(Account.class,
                    MethodType.methodType(void.class, String.class, String.class, BigDecimal.class));

            // findVirtual to a method taking a BigDecimal and returning BigDecimal.
            withFee = lookup.findVirtual(Account.class, "withFee",
                    MethodType.methodType(BigDecimal.class, BigDecimal.class));
        } catch (ReflectiveOperationException e) {
            // A wrong name/MethodType fails HERE, at creation — type-safe up front.
            throw new ExceptionInInitializerError(e);
        }
    }

    public String serialize(Account a) throws Throwable {
        // invoke: near direct-call speed, access already checked at lookup, no boxing of refs.
        String id      = (String) getId.invoke(a);
        String holder  = (String) getHolder.invoke(a);
        BigDecimal bal = (BigDecimal) getBalance.invoke(a);
        return "{\"id\":\"" + id + "\",\"holder\":\"" + holder + "\",\"balance\":" + bal + "}";
    }

    public Account create(String id, String holder, BigDecimal bal) throws Throwable {
        return (Account) ctor.invoke(id, holder, bal);   // construct via handle
    }

    public BigDecimal applyFee(Account a, BigDecimal fee) throws Throwable {
        return (BigDecimal) withFee.invoke(a, fee);       // dynamic virtual dispatch via handle
    }
}
