package com.bank.mh;

import com.bank.mh.model.Account;
import com.bank.mh.serde.HandleSerializer;
import java.math.BigDecimal;
import java.util.logging.*;

public class HandleDemo {
    private static final Logger log = Logger.getLogger(HandleDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Throwable {
        var serializer = new HandleSerializer();

        // Construct accounts via the constructor handle.
        Account rajesh = serializer.create("SAV2001", "Rajesh", new BigDecimal("1000000.00"));
        Account priya  = serializer.create("CUR3001", "Priya",  new BigDecimal("250000.00"));

        // Serialize via cached getter handles (fast, repeated).
        log.info(() -> safe(() -> "Rajesh JSON: " + serializer.serialize(rajesh)));
        log.info(() -> safe(() -> "Priya  JSON: " + serializer.serialize(priya)));

        // Dynamic virtual-method dispatch via a handle.
        BigDecimal afterFee = serializer.applyFee(rajesh, new BigDecimal("50.00"));
        log.info(() -> "Rajesh balance after Rs.50 fee (via handle): Rs." + afterFee);
        log.info("Method handles: type-checked once, access-checked once, near direct-call speed");
    }

    private static String safe(ThrowingSupplier s) {
        try { return s.get(); } catch (Throwable t) { return "error: " + t; }
    }
    interface ThrowingSupplier { String get() throws Throwable; }
}
